toolScript:
// State
        let state = { a: 0, b: 0, c: 0, gate: 'AND', inputs: 2, customEq: '(A | B) & !C' };
        // Configuration Data
        const gateInfo = {
            'AND': { desc: 'Output is HIGH only if ALL inputs are HIGH.', math: 'Y = A \\cdot B' },
            'OR': { desc: 'Output is HIGH if ANY input is HIGH.', math: 'Y = A + B' },
            'NOT': { desc: 'Inverts the input. (Only input A is used).', math: 'Y = \\overline{A}' },
            'NAND': { desc: 'Output is LOW only if ALL inputs are HIGH.', math: 'Y = \\overline{A \\cdot B}' },
            'NOR': { desc: 'Output is LOW if ANY input is HIGH.', math: 'Y = \\overline{A + B}' },
            'XOR': { desc: 'Output is HIGH if inputs are different (Odd parity).', math: 'Y = A \\oplus B' },
            'XNOR': { desc: 'Output is HIGH if inputs are equal (Even parity).', math: 'Y = \\overline{A \\oplus B}' },
            'CUSTOM': { desc: 'User defined boolean expression.', math: 'Y = f(x)' }
        };
        function setInputs(count) {
            state.inputs = count;
            // UI Toggle States
            document.getElementById('mode-2').className = count === 2 ? 'px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider bg-emerald-100 text-emerald-700 transition-all shadow-sm' : 'px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider text-slate-500 hover:bg-slate-50 transition-all';
            document.getElementById('mode-3').className = count === 3 ? 'px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider bg-emerald-100 text-emerald-700 transition-all shadow-sm' : 'px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider text-slate-500 hover:bg-slate-50 transition-all';
            // Show/Hide Input C
            const containerC = document.getElementById('container-c');
            const thC = document.getElementById('th-c');
            const btnNot = document.getElementById('btn-not');
            if (count === 3) {
                containerC.classList.remove('hidden');
                setTimeout(() => containerC.classList.remove('opacity-0', 'translate-y-4', 'scale-90'), 10);
                thC.classList.remove('hidden');
                btnNot.disabled = true; // Disable NOT for 3 inputs typically
                btnNot.classList.add('opacity-50', 'cursor-not-allowed');
                if (state.gate === 'NOT') setGate('AND'); // Fallback
            } else {
                containerC.classList.add('opacity-0', 'translate-y-4', 'scale-90');
                setTimeout(() => containerC.classList.add('hidden'), 300);
                thC.classList.add('hidden');
                btnNot.disabled = false;
                btnNot.classList.remove('opacity-50', 'cursor-not-allowed');
            }
            render();
        }
        function toggleInput(key) {
            state[key] = state[key] === 1 ? 0 : 1;
            render();
        }
        function setGate(gateType) {
            state.gate = gateType;
            // UI Button States
            document.querySelectorAll('.gate-selector').forEach(btn => {
                if (btn.innerText.includes(gateType)) btn.classList.add('active');
                else btn.classList.remove('active');
            });
            // Toggle Custom Input visibility
            const stdInfo = document.getElementById('standard-info');
            const custInfo = document.getElementById('custom-input-container');
            if (gateType === 'CUSTOM') {
                stdInfo.classList.add('hidden');
                custInfo.classList.remove('hidden');
                updateCustomLogic();
            } else {
                stdInfo.classList.remove('hidden');
                custInfo.classList.add('hidden');
                // Update Description & Math
                const info = gateInfo[gateType];
                document.getElementById('gate-description').innerText = info.desc;
                let mathStr = info.math;
                // Adjust Math string for 3 inputs if needed
                if (state.inputs === 3) {
                    if (gateType === 'AND') mathStr = 'Y = A \\cdot B \\cdot C';
                    if (gateType === 'OR') mathStr = 'Y = A + B + C';
                    if (gateType === 'XOR') mathStr = 'Y = A \\oplus B \\oplus C';
                    if (gateType === 'NAND') mathStr = 'Y = \\overline{A \\cdot B \\cdot C}';
                    if (gateType === 'NOR') mathStr = 'Y = \\overline{A + B + C}';
                    if (gateType === 'XNOR') mathStr = 'Y = \\overline{A \\oplus B \\oplus C}';
                }
                const eqDisplay = document.getElementById('equation-display');
                eqDisplay.innerText = `$$ ${mathStr} $$`;
                if (window.MathJax) MathJax.Hub.Queue(["Typeset", MathJax.Hub, eqDisplay]);
            }
            render();
        }
        function updateCustomLogic() {
            state.customEq = document.getElementById('custom-expression').value || '0';
            render();
        }
        function evaluateLogic(a, b, c, gate) {
            try {
                if (gate === 'CUSTOM') {
                    // Safe parser for custom expression
                    // Replace user syntax with JS syntax
                    let eq = state.customEq.toUpperCase()
                        .replace(/AND/g, '&&').replace(/OR/g, '||').replace(/NOT/g, '!')
                        .replace(/XOR/g, '^') // Bitwise XOR works for 0/1 integers
                        .replace(/[^ABC01&|^!() ]/g, ''); // Sanitize
                    // Create function scope variables
                    const A = a, B = b, C = c;
                    // Evaluate
                    const result = new Function('A', 'B', 'C', `return (${eq}) ? 1 : 0`)(A, B, C);
                    document.getElementById('custom-error').innerText = '';
                    return result;
                }
                switch (gate) {
                    case 'AND': return state.inputs === 3 ? (a && b && c) : (a && b);
                    case 'OR': return state.inputs === 3 ? (a || b || c) : (a || b);
                    case 'NOT': return !a ? 1 : 0;
                    case 'NAND': return state.inputs === 3 ? (!(a && b && c) ? 1 : 0) : (!(a && b) ? 1 : 0);
                    case 'NOR': return state.inputs === 3 ? (!(a || b || c) ? 1 : 0) : (!(a || b) ? 1 : 0);
                    case 'XOR': return state.inputs === 3 ? ((a ^ b ^ c) ? 1 : 0) : ((a ^ b) ? 1 : 0); // Logic: Odd parity
                    case 'XNOR': return state.inputs === 3 ? ((a ^ b ^ c) ? 0 : 1) : ((a ^ b) ? 0 : 1); // Logic: Even parity
                    default: return 0;
                }
            } catch (e) {
                if (gate === 'CUSTOM') document.getElementById('custom-error').innerText = 'Syntax Error';
                return 0;
            }
        }
        function renderSVG() {
            // Dynamic Path Drawing
            const is3 = state.inputs === 3;
            const pathA = document.getElementById('path-in-a');
            const pathB = document.getElementById('path-in-b');
            const pathC = document.getElementById('path-in-c');
            // Coordinates
            // Box is centered at x=110, y=50 (approx center of gate group transform)
            // Inputs start at x=0
            if (is3) {
                pathA.setAttribute('d', 'M 0 20 C 40 20, 40 30, 80 30'); // Top to top-input
                pathB.setAttribute('d', 'M 0 70 L 80 70');              // Mid to mid-input
                pathC.setAttribute('d', 'M 0 120 C 40 120, 40 110, 80 110'); // Bot to bot-input
                pathC.style.opacity = '1';
                // Adjust Gate Label Position for 3 inputs visual balance
                document.getElementById('gate-svg-container').setAttribute('transform', 'translate(80, 20)');
            } else {
                pathA.setAttribute('d', 'M 0 35 C 40 35, 40 50, 80 50'); // Top-mid
                pathB.setAttribute('d', 'M 0 105 C 40 105, 40 90, 80 90'); // Bot-mid
                pathC.style.opacity = '0';
                // Adjust Gate
                document.getElementById('gate-svg-container').setAttribute('transform', 'translate(80, 20)');
            }
        }
        function render() {
            renderSVG();
            const out = evaluateLogic(state.a, state.b, state.c, state.gate);
            // Update UI Nodes (Inputs)
            const updateNode = (id, val) => {
                const el = document.getElementById(id);
                el.innerText = val;
                el.className = `input-toggle ${val ? 'input-high' : 'input-low'} mx-auto`;
            };
            updateNode('input-a', state.a);
            updateNode('input-b', state.b);
            if (state.inputs === 3) updateNode('input-c', state.c);
            // Update Output Node
            const nodeOut = document.getElementById('output-node');
            const nodeVal = document.getElementById('output-val');
            const nodeGlow = document.getElementById('output-glow');
            nodeVal.innerText = out;
            nodeOut.className = `w-24 h-24 rounded-[2rem] border-4 flex items-center justify-center text-5xl font-black transition-all duration-300 relative ${out ? 'bg-emerald-500 border-emerald-400 text-white shadow-[0_0_30px_rgba(16,185,129,0.4)]' : 'bg-slate-800 border-slate-700 text-slate-600'}`;
            nodeGlow.style.opacity = out ? '0.6' : '0';
            // Update SVG Styles
            const setPath = (id, active) => {
                const p = document.getElementById(id);
                p.classList.toggle('signal-active', !!active);
                p.classList.toggle('signal-inactive', !active);
            };
            setPath('path-in-a', state.a);
            setPath('path-in-b', state.b);
            if (state.inputs === 3) setPath('path-in-c', state.c);
            setPath('path-out', out);
            document.getElementById('gate-icon').classList.toggle('gate-active', !!out);
            document.getElementById('gate-label').textContent = state.gate === 'CUSTOM' ? 'ƒ(x)' : state.gate;
            // Generate Truth Table
            const tbody = document.getElementById('truth-table-body');
            tbody.innerHTML = '';
            // Generate rows: 0 to 2^n - 1
            const rows = state.inputs === 3 ? 8 : 4;
            for (let i = 0; i < rows; i++) {
                // Extract bits
                let ta = 0, tb = 0, tc = 0;
                if (state.inputs === 3) {
                    ta = (i >> 2) & 1;
                    tb = (i >> 1) & 1;
                    tc = i & 1;
                } else {
                    ta = (i >> 1) & 1;
                    tb = i & 1;
                }
                const res = evaluateLogic(ta, tb, tc, state.gate);
                // Highlight current state
                const isCurrent = (state.inputs === 3)
                    ? (ta === state.a && tb === state.b && tc === state.c)
                    : (ta === state.a && tb === state.b);
                const tr = document.createElement('tr');
                tr.className = isCurrent
                    ? 'bg-emerald-50 font-black text-emerald-800 scale-100 ring-2 ring-emerald-100 z-10 relative transition-all'
                    : 'border-b border-slate-50 text-slate-500 hover:bg-slate-50 transition-colors';
                let html = `<td class="py-3">${ta}</td><td class="py-3">${tb}</td>`;
                if (state.inputs === 3) html += `<td class="py-3">${tc}</td>`;
                html += `<td class="py-3 text-right font-black ${res ? 'text-emerald-500' : 'text-slate-300'}">${res}</td>`;
                tr.innerHTML = html;
                tbody.appendChild(tr);
            }
        }
        // Global Scroll Logic
        // Initialize
        window.onload = function () {
            setInputs(2);
            render();
        };
